WHERE is_deleted = 0

    AND (config_name LIKE CONCAT('%', #{keyword}, '%')
         OR work_center LIKE CONCAT('%', #{keyword}, '%'))


    AND andon_type_id = #{andonTypeId}


    AND status = #{status}

